    def absorb(self, args):
        """
        Given an `args` sequence of expressions, return a new list of expression
        applying absorption and negative absorption.

        See https://en.wikipedia.org/wiki/Absorption_law

        Absorption::

            A & (A | B) = A, A | (A & B) = A

        Negative absorption::

            A & (~A | B) = A & B, A | (~A & B) = A | B
        """
        from sympy import And, Or, Not, simplify

        def apply_absorption(expr):
            if expr.has(And):
                for arg in expr.args:
                    if arg.has(Or):
                        for or_arg in arg.args:
                            if or_arg == expr.args[0] or Not(or_arg) == expr.args[0]:
                                return simplify(expr.args[0])
            if expr.has(Or):
                for arg in expr.args:
                    if arg.has(And):
                        for and_arg in arg.args:
                            if and_arg == expr.args[0] or Not(and_arg) == expr.args[0]:
                                return simplify(expr.args[0])
            return expr

        def apply_negative_absorption(expr):
            if expr.has(And):
                for arg in expr.args:
                    if arg.has(Or):
                        for or_arg in arg.args:
                            if Not(or_arg) == expr.args[0]:
                                return simplify(And(expr.args[0], or_arg))
            if expr.has(Or):
                for arg in expr.args:
                    if arg.has(And):
                        for and_arg in arg.args:
                            if Not(and_arg) == expr.args[0]:
                                return simplify(Or(expr.args[0], and_arg))
            return expr

        new_args = []
        for arg in args:
            arg = apply_absorption(arg)
            arg = apply_negative_absorption(arg)
            new_args.append(arg)

        return new_args
