            for element in root:
                tag = element.tag.split('}')[-1]  # Remove namespace
                if tag == 'Alias':
                    parsed_data['alias'] = element.text
                elif tag == 'Link':
                    link_data = {}
                    for attr, value in element.attrib.items():
                        link_data[attr] = value
                    if 'rel' in link_data:
                        parsed_data[link_data['rel']] = link_data
            return parsed_data
        except ET.ParseError:
            raise ValueError("Document is not a valid JSON or XRD format")
